package com.parking.notification.client;

import org.springframework.cloud.openfeign.FeignClient;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

import java.util.List;

/**
 * Synchronous REST calls to the parking service, generated by OpenFeign from this interface.
 * Without a URL, "parking-service" is resolved through Eureka. Use {@link ResilientParkingClient},
 * which adds the circuit breaker, retry and fallback.
 */
@FeignClient(name = "parking-service", url = "${parking-service.url:}")
public interface ParkingServiceClient {

    @GetMapping("/api/reservations/{id}")
    ReservationDto getReservation(@PathVariable("id") int id);

    @GetMapping("/api/reservations")
    List<ReservationDto> getReservations(@RequestParam("userId") String userId);
}
